/* JPA & Hibernate §2 — what each @GeneratedValue strategy costs on each database.
   Pre-authored from Hibernate 7's dialects; round-trip counts assume 100 inserts
   in one transaction with hibernate.jdbc.batch_size=50. */
(function () {
  'use strict';
  var reg = globalThis.LMSandbox.reg, H = globalThis.LMHighlight;

  reg('id-strategy', function (el) {
    var strat = el.querySelector('[data-sb-strategy]');
    var db = el.querySelector('[data-sb-db]');
    var out = el.querySelector('[data-sb-out]');

    var DDL = {
      identity: {
        postgres: 'create table product (id bigint generated by default as identity, sku varchar(16) not null, primary key (id))',
        mysql:    'create table product (id bigint not null auto_increment, sku varchar(16) not null, primary key (id)) engine=InnoDB',
        h2:       'create table product (id bigint generated by default as identity, sku varchar(16) not null, primary key (id))',
        oracle:   'create table product (id number(19,0) generated as identity, sku varchar2(16 char) not null, primary key (id))'
      },
      seq1:  { generic: 'create sequence product_seq start with 1 increment by 1\ncreate table product (id bigint not null, sku varchar(16) not null, primary key (id))' },
      seq50: { generic: 'create sequence product_seq start with 1 increment by 50\ncreate table product (id bigint not null, sku varchar(16) not null, primary key (id))' },
      table: { generic: 'create table hibernate_sequences (sequence_name varchar(255) not null, next_val bigint, primary key (sequence_name))\ninsert into hibernate_sequences(sequence_name, next_val) values (\'product\', 1)\ncreate table product (id bigint not null, sku varchar(16) not null, primary key (id))' },
      uuid: {
        postgres: 'create table product (id uuid not null, sku varchar(16) not null, primary key (id))',
        mysql:    'create table product (id binary(16) not null, sku varchar(16) not null, primary key (id)) engine=InnoDB',
        h2:       'create table product (id uuid not null, sku varchar(16) not null, primary key (id))',
        oracle:   'create table product (id raw(16) not null, sku varchar2(16 char) not null, primary key (id))'
      }
    };
    var INSERT = {
      identity: { postgres: 'insert into product (sku,id) values (?,default)', h2: 'insert into product (sku,id) values (?,default)', mysql: 'insert into product (sku) values (?)', oracle: 'insert into product (sku) values (?)' },
      other: 'insert into product (sku,id) values (?,?)'
    };
    var DBNAME = { postgres: 'PostgreSQL', mysql: 'MySQL', h2: 'H2', oracle: 'Oracle' };

    function render() {
      var s = strat.value, d = db.value;
      var ddl, insert, trips, batch, kind, title, body;
      var mysqlNoSeq = d === 'mysql' && (s === 'seq1' || s === 'seq50');

      if (s === 'identity') {
        ddl = DDL.identity[d]; insert = INSERT.identity[d];
        trips = '100 — one per row, each executed immediately so the generated key can be read back';
        batch = 'No. Hibernate must know the id to manage the entity, and the database only reveals it after the insert, so inserts cannot be deferred or batched.';
        kind = 'gotcha'; title = 'Simple, and it disables insert batching';
        body = 'Fine for small write volumes and the only choice when you cannot create a sequence. For a bulk import it is the slowest option: every <code>persist</code> is a round trip, and §9 cannot help you.';
      } else if (s === 'seq1') {
        ddl = mysqlNoSeq ? DDL.table.generic : DDL.seq1.generic; insert = INSERT.other;
        trips = mysqlNoSeq ? '202 — MySQL has no sequences, so Hibernate silently falls back to a table generator: a select and an update per id, plus 2 batched insert statements'
                           : '102 — 100 <code>select next value</code> calls plus 2 batched insert statements of 50 rows';
        batch = 'Yes. Ids are known before the insert, so the inserts queue up and go out in batches at flush.';
        kind = 'note'; title = 'Batchable, but one round trip per id';
        body = 'Every id costs a database call. Correct, portable, and about as slow as IDENTITY for writes unless you raise the allocation size.';
      } else if (s === 'seq50') {
        ddl = mysqlNoSeq ? DDL.table.generic.replace('values (\'product\', 1)', 'values (\'product\', 1)   -- allocationSize 50 applies here too') : DDL.seq50.generic; insert = INSERT.other;
        trips = mysqlNoSeq ? '6 — 2 table-generator select+update pairs plus 2 batched insert statements'
                           : '4 — 2 <code>select next value</code> calls (each worth 50 ids) plus 2 batched insert statements';
        batch = 'Yes, and the sequence is consulted only every 50 inserts. This is Hibernate\'s default and the recommended choice wherever sequences exist.';
        kind = 'good'; title = 'The default, and the fastest portable option';
        body = 'The pooled optimiser hands out <code>increment by 50</code> ids in memory. Gaps appear when the application restarts (unused ids in the current block are lost) — harmless, unless someone is reading meaning into the numbers.';
      } else if (s === 'table') {
        ddl = DDL.table.generic; insert = INSERT.other;
        trips = '6 — each block of 50 ids is a <code>select … for update</code> and an <code>update</code> in a separate transaction, plus 2 batched inserts';
        batch = 'Yes, but every id block takes a row lock on <code>hibernate_sequences</code>, which serialises all inserting threads across the whole application.';
        kind = 'gotcha'; title = 'Portable to anything, and the slowest under load';
        body = 'Exists for databases without sequences or identity columns. On anything modern it is a contention point waiting to happen; use SEQUENCE or IDENTITY instead.';
      } else {
        ddl = DDL.uuid[d]; insert = INSERT.other;
        trips = '2 — ids are generated in the JVM, so only the 2 batched insert statements touch the database';
        batch = 'Yes. No database involvement at all until flush.';
        kind = 'note'; title = 'No round trips, but mind the index';
        body = 'A random (version 4) UUID scatters inserts across the whole primary-key index, which hurts insert throughput and cache locality on large tables. Hibernate\'s <code>@UuidGenerator(style = TIME)</code> or a version-7 UUID keeps keys roughly ordered; and a 16-byte key makes every foreign key and index 16 bytes wider than a bigint.';
      }

      var icon = kind === 'good' ? '<path d="M20 6 9 17l-5-5"/>' : kind === 'gotcha'
        ? '<path d="M12 9v4m0 4h.01M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/>'
        : '<circle cx="12" cy="12" r="9"/><path d="M12 16v-5m0-3h.01"/>';

      out.innerHTML =
        '<div class="lm-stepper-label">DDL Hibernate generates on ' + H.esc(DBNAME[d]) + '</div>' +
        H.renderCode(ddl, { lang: 'sql', noBar: true }) +
        '<div class="lm-stepper-label mt-3">Insert statement</div>' +
        H.renderCode(insert, { lang: 'sql', noBar: true }) +
        '<dl class="lm-kv mt-3">' +
        '<dt>Round trips for 100 inserts</dt><dd>' + trips + '</dd>' +
        '<dt>JDBC batching</dt><dd>' + batch + '</dd>' +
        '</dl>' +
        '<div class="lm-callout lm-callout--' + kind + '" style="margin-top:.9rem">' +
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">' + icon + '</svg>' +
        '<div><div class="lm-callout-title">' + H.esc(title) + '</div>' + body + '</div></div>';
    }

    strat.addEventListener('change', render);
    db.addEventListener('change', render);
    render();
  });
})();
